Utf8Stream() throws Exception
    {
        Utf8StreamJsonParser p = new Utf8StreamJsonParser();
        byte[] data = p.getUtf8Bytes(" ⁇ ");
        assertEquals(1, data.length);
        assertEquals((byte) 0xEF, data[0]);

        // and then with UTF-8 encoded bytes
        p = new Utf8StreamJsonParser();
        data = p.getUtf8Bytes(" ⁇ ");
        assertEquals(1, data.length);
        assertEquals((byte) 0xEF, data[0]);
    }

Utf8Stream() throws Exception
    {
        Utf8StreamJsonParser p = new Utf8StreamJsonParser();
        p.setReader(new StringReader("abc"));
        assertEquals(JsonToken.VALUE_STRING, p.nextToken());
        assertEquals("abc", p.getText());
        assertEquals(3, p.getTextLength());
        assertEquals(3, p.getTextOffset());

        p.close();
    }

