Utf8Stream() throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream(100);
        JsonFactory f = new JsonFactory();
        f.configure(JsonFactory.Feature.ESCAPE_NON_ASCII, true);
        JsonGenerator g = f.createJsonGenerator(bytes, JsonEncoding.UTF8);
        g.writeStartObject();
        g.writeFieldName("name");
        g.writeString("Bob");
        g.writeFieldName("age");
        g.writeNumber(33);
        g.writeFieldName("eyeColor");
        g.writeString("blue");
        g.writeEndObject();
        g.close();

        _testUtf8Stream(bytes, "name", "Bob", 33, "eyeColor", "blue");
    }
